INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (406, 1, 'vcpu current', '`<vcpu>` 의 **current** 속성은 무엇을 정할까요?', '최대보다 적게 켤 수 있어요.', NULL, NULL, '[]', 'choice', '["vCPU 를 호스트 CPU 에 고정할지", "게스트가 쓸 수 있는 메모리 양", "최대 vCPU 수보다 적은 수만 켜 둘지", "vCPU 스케줄링의 우선순위 값"]', 2, 'libvirt 문서는 current 속성이 최대 개수보다 적은 가상 CPU 를 활성화할지를 제어한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt 도메인 XML 형식", "url": "https://libvirt.org/formatdomain.html"}]'),
  (406, 2, 'vCPU 핫플러그', '`<vcpus>` 의 **hotpluggable** 속성에 대한 설명으로 맞는 것은 무엇일까요?', '비활성 vCPU 와 관련이 있어요.', NULL, NULL, '[]', 'choice', '["모든 vCPU 는 항상 핫플러그가 가능해서 정할 일이 없다", "핫플러그 가능 여부이며 비활성 vCPU 는 모두 가능해야 한다", "KVM 외의 모든 하이퍼바이저에서도 똑같이 쓸 수 있다", "핫플러그된 vCPU 는 항상 호스트 CPU 에 고정되어 버린다"]', 1, '문서는 hotpluggable 이 vCPU 를 핫플러그·핫언플러그할 수 있는지를 제어하며 모든 비활성 vCPU 는 hotpluggable 이어야 하고 QEMU 에서만 지원된다고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt 도메인 XML 형식", "url": "https://libvirt.org/formatdomain.html"}]'),
  (406, 3, 'vcpupin 기본', '`<vcpupin>` 을 **생략** 하면 vCPU 는 어디에 고정될까요?', '제한이 없는 쪽이에요.', NULL, NULL, '[]', 'choice', '["모든 물리 CPU 에 고정(사실상 제한 없음)", "0번 CPU 에만 고정되어 버린다", "게스트가 시작될 때 임의로 하나에 고정된다", "고정이 불가능해 오류가 난다"]', 0, '문서는 vcpupin 에서 지정하지 않으면 vCPU 가 기본으로 모든 물리 CPU 에 고정된다고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt 도메인 XML 형식", "url": "https://libvirt.org/formatdomain.html"}]'),
  (406, 4, 'emulatorpin', '`<emulatorpin>` 은 어떤 스레드를 고정할까요?', 'vCPU 가 아닌 쪽이에요.', NULL, NULL, '[]', 'choice', '["게스트에 속한 모든 vCPU 스레드 전체", "IOThread 스레드만 골라서 고정한다", "게스트 안에서 돌아가는 프로세스", "에뮬레이터 스레드(vCPU·IOThread 제외)"]', 3, '문서는 emulatorpin 이 vCPU 와 IOThread 를 제외한 "에뮬레이터" 스레드 집합을 호스트 CPU 에 고정한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt 도메인 XML 형식", "url": "https://libvirt.org/formatdomain.html"}]'),
  (406, 5, 'shares 의 단위', '`<cputune>` 의 **shares** 값은 어떤 성격일까요?', '단위가 없는 상대값이에요.', NULL, NULL, '[]', 'choice', '["밀리초 단위의 절대 시간", "허용되는 CPU 코어 수", "단위 없는 상대적 가중치", "MHz 단위의 클럭 값"]', 2, '문서는 shares 가 단위가 없는 상대적 가중치이며 범위는 cgroups v1 에서 [2, 262144], v2 에서 [1, 10000] 이라고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt 도메인 XML 형식", "url": "https://libvirt.org/formatdomain.html"}]'),
  (406, 6, 'quota 의 음수', '`<cputune>` 의 **quota** 가 음수이면 무엇을 뜻할까요?', '무제한이에요.', NULL, NULL, '[]', 'choice', '["vCPU 가 곧바로 정지되어 대기한다", "무한 대역폭(제어 없음)", "오류로 취급되어 거부된다", "기본값 1000 으로 자동 대체된다"]', 1, '문서는 quota 가 마이크로초 단위의 최대 대역폭이며 음수이면 무한 대역폭(제어 없음)이라고 설명합니다. 양수는 [1000, 17592186044415] 범위여야 합니다.', NULL, NULL, NULL, '[{"title": "libvirt 도메인 XML 형식", "url": "https://libvirt.org/formatdomain.html"}]'),
  (406, 7, 'period 의 단위', '`<cputune>` 의 **period** 는 어떤 단위와 범위로 정할까요?', '마이크로초예요.', NULL, NULL, '[]', 'choice', '["마이크로초, 범위 [1000, 1000000]", "밀리초 단위, 범위 [1, 1000]을 쓴다", "초 단위이고 범위 [1, 60]을 쓴다", "클럭 틱 단위, 범위 [0, 255]를 쓴다"]', 0, '문서는 period 를 집행 간격(마이크로초)으로 설명하며 범위는 [1000, 1000000] 이고 0 은 값 없음을 뜻한다고 합니다.', NULL, NULL, NULL, '[{"title": "libvirt 도메인 XML 형식", "url": "https://libvirt.org/formatdomain.html"}]'),
  (406, 8, 'cpu mode 기본', '`<cpu>` 에서 **mode 를 주지 않으면** 기본은 무엇일까요?', '영구 게스트에 같은 하드웨어를 보여 줘요.', NULL, NULL, '[]', 'choice', '["host-passthrough", "host-model", "maximum", "custom"]', 3, '문서는 custom 이 mode 를 주지 않을 때의 기본이며, 영구 게스트가 어느 호스트에서 부팅하든 같은 하드웨어를 보게 한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt 도메인 XML 형식", "url": "https://libvirt.org/formatdomain.html"}]'),
  (406, 9, 'host-passthrough 의 주의', '**host-passthrough** 모드에서 문서가 경고하는 것은 무엇일까요?', '마이그레이션이 위험해요.', NULL, NULL, '[]', 'choice', '["게스트가 호스트의 CPU 를 쓸 수 없다", "가상 CPU 가 하나로 제한된다", "호스트가 똑같지 않으면 마이그레이션이 위험하다", "Windows 게스트에서만 동작한다"]', 2, '문서는 host-passthrough 가 게스트 CPU 를 libvirt 가 모델링하지 않는 부분까지 호스트와 일치시키며, 호스트가 동일하지 않으면 마이그레이션이 위험하고 버그가 생기면 스스로 해결해야 한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "libvirt 도메인 XML 형식", "url": "https://libvirt.org/formatdomain.html"}]'),
  (406, 10, '호스트와 그대로', '게스트 CPU 가 **호스트 CPU 와 그대로 일치** 하게 하는 mode 값입니다. 빈칸을 채우세요.', '"통과"라는 이름이에요.', NULL, NULL, '[]', 'fill', '["host-passthrough", "host-model", "custom", "emulated"]', NULL, 'host-passthrough 는 게스트 CPU 를 호스트 CPU 와 일치시킵니다. host-model 은 호스트 모델을 시작 직전에 복사합니다.', '[0]', '<cpu mode=''{0}''/>', NULL, '[{"title": "libvirt 도메인 XML 형식", "url": "https://libvirt.org/formatdomain.html"}]'),
  (406, 11, 'vcpu placement', '`<vcpu>` 의 **placement** 가 `cpuset` 을 지정했을 때 기본으로 갖는 값입니다. 빈칸을 채우세요.', '"고정" 이에요.', NULL, NULL, '[]', 'fill', '["static", "auto", "dynamic", "manual"]', NULL, 'placement 는 static 또는 auto 이며, numatune 의 placement 나 cpuset 을 지정하면 기본이 static 입니다.', '[0]', '<vcpu placement=''{0}'' cpuset=''0-3''>4</vcpu>', NULL, '[{"title": "libvirt 도메인 XML 형식", "url": "https://libvirt.org/formatdomain.html"}]'),
  (406, 12, 'vCPU 를 고정하기', 'vCPU 를 특정 호스트 CPU 에 고정하는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '개수 → 고정 → 분리 → 시작이에요.', NULL, NULL, '[]', 'order', '["`<vcpu>` 로 게스트의 vCPU 수를 정한다", "`<cputune>` 의 vcpupin 으로 각 vCPU 를 호스트 CPU 에 고정한다", "emulatorpin 으로 에뮬레이터 스레드를 다른 CPU 로 분리한다", "게스트를 시작하면 고정이 적용된다"]', NULL, '문서의 vcpu·cputune 설명을 이은 큰 줄기입니다. QEMU 에서는 vcpupin·emulatorpin 이 에뮬레이터 실행 후 적용됩니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "libvirt 도메인 XML 형식", "url": "https://libvirt.org/formatdomain.html"}]');
